/* v2.13.0 Language of the time: researched and checked 25 October 2026; every entry has two or more independent sources */
const LT=[
 {id:"lt-half-caste",term:"half-caste",period:"Recorded in English from the mid-18th century (Merriam-Webster first known use 1758); common in British, colonial and Australian official and everyday usage into the late 20th century.",meaning_then:"A label for a person whose parents were of different 'races', especially (in British colonial usage) a child of a European and an Indian parent; used widely in colonial administration, welfare and police records and in everyday speech in Britain.",why_changed:"The word rests on the idea that a person is a 'half' of something, implying impurity; dictionaries now label it offensive or contemptuous, and UK judicial and equality guidance says it should be avoided.",hub_uses_now:"'Mixed ethnic background' or 'from the Mixed ethnic group' (UK official usage), or 'mixed heritage', 'dual heritage' or 'mixed race' as people choose for themselves.",when_kept:"Kept only inside quotations from historical records, titles of works or organisations and official files (for example colonial or welfare records), marked as the term of the time, with a short note that it is now regarded as offensive and what the hub uses instead. Not used in the hub's own voice.",self_id:"",note:"",debated:false,re:"\\bhalf[- ]caste\\b",named:false,covers:["half-caste"],src:[SRCQ("Merriam-Webster, half-caste","https://www.merriam-webster.com/dictionary/half-caste","Supports the language page (language of the time)","one of mixed racial descent : half-breed | label: offensive | First known use: 1758, in the meaning defined above"),SRCQ("Dictionary.com (incl. Collins English Dictionary), half-caste","https://www.dictionary.com/browse/half-caste","Supports the language page (language of the time)","a contemptuous term used to refer to a person of mixed racial or ethnic descent. | British English: a person having parents of different races, esp the offspring of a European and an Indian"),SRCQ("5 Essex Court (barristers' chambers), summary of the Judicial College Equal Treatment Bench Book (2024 edition) terminology guidance","https://www.5essex.co.uk/the-latest-edition-of-the-equal-treatment-bench-book-gives-guidance-on-the-appropriate-use-of-terminology/","Supports the language page (language of the time)","'Half-caste' is generally considered offensive and should be avoided."),SRCQ("EqualiTeach, Equality terminology (hosted by the Royal Institution)","https://www.rigb.org/sites/default/files/attachments/equality_terminology__equaliteach_0.pdf","Supports the language page (language of the time)","An old-fashioned term used to describe someone of dual heritage. ... implies that they are 'half pure'")]},
 {id:"lt-coloured-uk",term:"coloured (UK and US 20th-century usage)",period:"In common, widespread use in Britain and the United States well into the 20th century; used in UK official surveys into the 1970s; fell out of favour from the 1960s.",meaning_then:"A general word for anyone who was not white, used by officials (for example interviewers in the 1970s General Household Survey recorded whether people were 'White or coloured'), employers and trade unions, and also by Black-led organisations such as the League of Coloured Peoples (founded 1931) and the US NAACP.",why_changed:"Attitudes changed by the 1960s; the word lumps everyone who is not white into one group defined against whiteness and is linked to segregation and 'colour bar' practices. Dictionaries now mark it dated and usually offensive; UK judicial guidance says it must be avoided.",hub_uses_now:"Specific ethnic groups (for example Black Caribbean, Black African, Indian), or 'ethnic minorities' / 'people from ethnic minority backgrounds' when grouping is unavoidable.",when_kept:"Kept in organisation names (League of Coloured Peoples, NAACP), document titles, survey categories and quotations from records such as union resolutions or Home Office papers, with a note explaining that it was the general term of the time for people who were not white and is now considered offensive. For the South African population group, see lt-coloured-south-africa.",self_id:"Merriam-Webster notes it is still occasionally used in self-reference by and between Black people (US); it remains in the NAACP's full name.",note:"Distinguish clearly from South African 'Coloured', which is a living self-identity.",debated:false,re:"\\b[Cc]oloured (people|peoples|person|workers|immigrants|communit(y|ies)|men|women)\\b|League of Coloured Peoples",named:false,covers:["coloured people"],src:[SRCQ("Merriam-Webster, colored (usage paragraph)","https://www.merriam-webster.com/dictionary/colored","Supports the language page (language of the time)","The adjective meanings of colored relating to race were formerly in common and widespread use well into the 20th century. | Attitudes toward them had changed, however, by the 1960s. | Colored remains in the full name of the NAACP"),SRCQ("GOV.UK History of Government blog, 50 years of collecting ethnicity data (2019)","https://history.blog.gov.uk/2019/03/07/50-years-of-collecting-ethnicity-data/","Supports the language page (language of the time)","White or 'coloured'"),SRCQ("TUC 150, Bristol bus boycott","https://tuc150.tuc.org.uk/stories/bristol-bus-boycott/","Supports the language page (language of the time)","the TGWU had passed a resolution that 'coloured' workers should not be employed as bus crews"),SRCQ("English Heritage, Dr Harold Moody blue plaque","https://www.english-heritage.org.uk/visit/blue-plaques/dr-harold-moody/","Supports the language page (language of the time)","From number 164 Moody ran the League of Coloured Peoples, which he founded in 1931."),SRCQ("5 Essex Court (barristers' chambers), summary of the Judicial College Equal Treatment Bench Book (2024 edition) terminology guidance","https://www.5essex.co.uk/the-latest-edition-of-the-equal-treatment-bench-book-gives-guidance-on-the-appropriate-use-of-terminology/","Supports the language page (language of the time)","'Coloured' is offensive and must be avoided.")]},
 {id:"lt-colour-bar",term:"colour bar",period:"Used in Britain from at least the interwar years to the 1960s; open discrimination was lawful until the Race Relations Act 1965 (public places) and 1968 (housing and employment).",meaning_then:"The name of the time for formal or informal rules excluding people who were not white from jobs, housing, pubs, dance halls, lodgings or ranks (for example the Bristol Omnibus Company's refusal to employ Black and Asian bus crews, ended in 1963, and the barrier to Black officers in the armed forces).",why_changed:"It is a historical description rather than an insult; the practices it named were made unlawful by the Race Relations Acts. Today the same practices are described as racial discrimination or racism.",hub_uses_now:"Keeps 'colour bar' as the historical name, and adds 'racial discrimination' in plain words.",when_kept:"Kept as the term of the time in accounts of the Bristol Bus Boycott, armed-forces barriers and similar events, in quotation marks on first use, with a one-line explanation.",self_id:"",note:"",debated:false,re:"\\bcolou?r bar\\b",named:true,covers:[],src:[SRCQ("Historic England (Heritage Calling), The story of the Bristol Bus Boycott (2023)","https://heritagecalling.com/2023/04/20/the-story-of-the-bristol-bus-boycott/","Supports the language page (language of the time)","This was known as a 'colour bar', and it caused uproar in the local black community."),SRCQ("TUC 150, Bristol bus boycott","https://tuc150.tuc.org.uk/stories/bristol-bus-boycott/","Supports the language page (language of the time)","It had a 'colour bar'. | ...where 500 bus workers had voted against the colour bar."),SRCQ("English Heritage, Dr Harold Moody blue plaque","https://www.english-heritage.org.uk/visit/blue-plaques/dr-harold-moody/","Supports the language page (language of the time)","implicit colour bar in the British Armed Forces that had prevented the appointment of black officers")]},
 {id:"lt-coloured-south-africa",term:"Coloured (South Africa)",period:"A census category from 1911; made a legal race classification by the Population Registration Act 1950; still a Statistics South Africa population group (Census 2022) and a living community identity.",meaning_then:"Under apartheid, a 'coloured person' was legally defined negatively as someone who was neither 'white' nor 'native'; the 1950 Act divided people into White, Black (then 'Native'), Coloured and Indian, and the category was later subdivided (for example 'Cape Coloured').",why_changed:"The classification was a cornerstone of apartheid and is rejected as a legal category. The word itself has not been abandoned: many people in South Africa identify as Coloured, while others contest the label or prefer names such as Camissa or Khoi and San heritage terms.",hub_uses_now:"Capitalised 'Coloured' when referring to the South African community or population group, with a note that it is a self-identity distinct from the British and American use of 'coloured'.",when_kept:"Kept, capitalised, in its South African sense in both historical and present-day contexts; when quoting apartheid legislation the hub explains that the legal definition was imposed and negative ('not white or native').",self_id:"Many South Africans identify as Coloured; Statistics South Africa still uses 'Coloured' as a population group. The identity is contested within the community (some prefer Camissa or Khoi/San identities).",note:"Supporters see Coloured as a distinct culture and community with its own history since the late 19th century; critics see the word as an apartheid imposition and prefer names rooted in indigenous Cape ancestry such as Camissa. The hub presents both and follows the person's own usage.",debated:true,re:"\\bCape Coloured\\b|\\bColoured (identity|South Africans|community)\\b",named:true,covers:[],src:[SRCQ("South African History Online, Parliament passes legislation separating people of South Africa into four distinct races","https://sahistory.org.za/dated-event/parliament-passes-legislation-separating-people-south-africa-four-distinct-races","Supports the language page (language of the time)","into four distinct races (White, Black, Coloured, and Indian) | through the Population Registration Act No. 30 of 1950"),SRCQ("Camissa Museum, Race classification","https://camissamuseum.co.za/index.php/orientation/race-classification","Supports the language page (language of the time)","one new classification called 'Coloured' | \"coloured person\" means a person who is not a white person or a native. | What Colonialism and Apartheid said YOU are!"),SRCQ("DataFirst (University of Cape Town), Statistics South Africa Census 2022, variable P07A_POP_GROUP","https://datafirst.uct.ac.za/dataportal/index.php/catalog/982/variable/V47","Supports the language page (language of the time)","Population group | 2: Coloured"),SRCQ("Mixed Race Studies, summary of Mohamed Adhikari, Not White Enough, Not Black Enough: Racial Identity in the South African Coloured Community (2005)","https://mixedracestudies.org/?p=7545","Supports the language page (language of the time)","being neither white nor black | functioned as a social identity from the time of its emergence in the late nineteenth century | a matter of intense political and ideological contestation")]},
 {id:"lt-negro",term:"Negro",period:"Used from the 18th to the 20th centuries, including by Black writers and organisations; fell out of favour from the 1960s and largely replaced in non-historical use by 'Black' (and 'African American' in the US) by the 1980s. The US Census dropped it in 2020.",meaning_then:"The standard word in English for a person of Black African ancestry, used in titles and names across the political spectrum: John Stuart Mill's reply 'The Negro Question' (1850), the 'Negro spiritual', Marcus Garvey's Universal Negro Improvement Association (founded in Jamaica, 1914), the United Negro College Fund and the US Negro Leagues.",why_changed:"Associated with segregation-era classification and racial hierarchy; Black civil-rights and Black Power movements promoted 'Black'. Dictionaries mark it dated and often offensive except in historical names.",hub_uses_now:"Black; Black African; Black Caribbean; African American (US contexts); 'African American spiritual' alongside the historical name.",when_kept:"Kept unchanged in organisation names (UNIA, UNCF, Negro Leagues), titles of works (Mill's 'The Negro Question'; 'Negro spirituals' collections) and census categories, with a note that it was the standard term of the time and is now dated. Exception: Thomas Carlyle's 1849 pro-slavery essay is named by its original title only with a warning; its 1853 retitled version contains a slur and is paraphrased, not reproduced, as are its insults.",self_id:"Merriam-Webster notes Negro is sometimes used by Black people in self-reference; organisations such as the UNCF and the Negro Leagues Baseball Museum keep it.",note:"",debated:false,re:"\\bNegro(es)?\\b",named:false,covers:[],src:[SRCQ("Merriam-Webster, Negro (usage paragraph)","https://www.merriam-webster.com/dictionary/Negro","Supports the language page (language of the time)","The terms Negro and, to a lesser extent, Negress were formerly in common use, | but began to fall out of favor in the 1960s, | and by the 1980s had largely been replaced in nonhistorical contexts by Black and African American."),SRCQ("International Slavery Museum (National Museums Liverpool), Guidance on subject sensitivity and language (24 October 2022)","https://images.liverpoolmuseums.org.uk/2022-11/ISM-guidance-subject-sensitivity-language-24-Oct-22.pdf","Supports the language page (language of the time)","A term used throughout the 18th to the 20th centuries to describe a person of African descent. | The word is considered derogatory and unacceptable today."),SRCQ("Library of Congress, Songs of America: Spirituals","https://www.loc.gov/collections/songs-of-america/articles-and-essays/musical-styles/ritual-and-worship/spirituals","Supports the language page (language of the time)","The African American spiritual (also called the Negro Spiritual)"),SRCQ("Parks Canada, Universal Negro Improvement Association National Historic Event","https://www.pc.gc.ca/apps/dfhd/page_nhs_eng.aspx?id=15477","Supports the language page (language of the time)","founded by Jamaican-born Marcus Garvey in 1914"),SRCQ("University of Stirling, John Stuart Mill 'On the Negro Question' Fraser's Magazine (1850)","https://campuspress.stir.ac.uk/hisu9g5/?p=333","Supports the language page (language of the time)","His writing was in response to an article published by Thomas Carlyle in 1849. | In this piece, Mill wishes to dispute the beliefs of Carlyle."),SRCQ("Glasgow Life Museums, Thomas Carlyle, historian, writer, racist","https://www.glasgowlife.org.uk/museums/legacies-of-slavery-and-empire/thomas-carlyle-historian-writer-racist","Supports the language page (language of the time)","vicious racial caricature and insult, with distressing imperialist metaphors"),SRCQ("Pew Research Center, What Census calls us / The changing categories the U.S. census has used to measure race (2020)","https://pewresearch.org/fact-tank/2020/02/25/the-changing-categories-the-u-s-has-used-to-measure-race/","Supports the language page (language of the time)","the bureau did decide to drop the word \"Negro\"")]},
 {id:"lt-west-indian",term:"West Indian / West Indies",period:"From the 16th century (Merriam-Webster first known use 1589); the usual British name for Caribbean people and places through the Windrush years (1948 onwards); still used, e.g. West Indies cricket.",meaning_then:"A person from, or connected with, the British colonies and islands of the Caribbean (the 'West Indies', a name from European colonial geography). Used officially (West India Royal Commission), in the press ('417 West Indians' on the Empire Windrush, 1948) and by Caribbean people themselves, including organisations of 'British West Indians'.",why_changed:"The name comes from colonial geography; from the 1970s many objected to describing people born in Britain as 'West Indian'. Official statistics moved to 'Afro-Caribbean' in the 1980s, then 'Black Caribbean' (1991 Census) and 'Caribbean' (2021).",hub_uses_now:"Caribbean or Black Caribbean (or the specific country, e.g. Jamaican, Trinidadian), and Black British for people born or raised here.",when_kept:"Kept in titles, newspaper quotations, organisation names and official bodies of the period (for example West India Royal Commission, West Indian Standing Conference, the West Indies cricket team, Bernard Coard's 1971 pamphlet title) and when quoting people who describe themselves that way.",self_id:"Still used by some older Caribbean-heritage people in Britain and in the name of the West Indies cricket team.",note:"",debated:false,re:"\\bWest Indian\\b",named:true,covers:[],src:[SRCQ("Merriam-Webster, West Indian","https://www.merriam-webster.com/dictionary/West%20Indian","Supports the language page (language of the time)","of, relating to, or characteristic of the West Indies | First known use: 1589, in the meaning defined above"),SRCQ("The National Archives, On the Record: Windrush 75 (podcast transcript)","https://cdn.nationalarchives.gov.uk/documents/on-the-record-windrush75.pdf","Supports the language page (language of the time)","Thirty of the 417 West Indians bound for Britain in the troopship Empire Windrush, have volunteered for the mines,"),SRCQ("GOV.UK History of Government blog, 50 years of collecting ethnicity data (2019)","https://history.blog.gov.uk/2019/03/07/50-years-of-collecting-ethnicity-data/","Supports the language page (language of the time)","many West Indians felt it inappropriate to describe people born in Britain as 'West Indian'."),SRCQ("History Today, How Windrush changed the Caribbean","https://www.historytoday.com/archive/feature/how-windrush-changed-caribbean","Supports the language page (language of the time)","As British West Indians … we are deeply concerned with what HAPPENS AT HOME.")]},
 {id:"lt-immigrant-pupils",term:"immigrant (of pupils and children, 1960s-70s)",period:"1960s to early 1970s school policy and statistics in England, e.g. DES Circular 7/65 (1965) and Department of Education and Science statistics until the early 1970s.",meaning_then:"Official policy spoke of 'immigrant children'. For statistics the Department of Education defined an immigrant child as one born abroad or born in the UK to parents from abroad who had arrived less than ten years earlier, so many British-born Black and Asian children were counted as 'immigrants'. Circular 7/65 recommended dispersing 'immigrant children' when they exceeded about one third of a school or class (the 'bussing' policy).",why_changed:"Researchers have shown the category was ill-defined and in practice colour-based; it labelled British-born children as outsiders. The statistics were contested in Parliament in the early 1970s and dispersal was abandoned.",hub_uses_now:"'Children born in Britain to Caribbean (or South Asian) parents', 'Black British children', or 'children of the Windrush generation' – with the official label quoted and explained.",when_kept:"Kept in quotation marks when citing circulars, statistics, school records and debates ('immigrant pupils', 'immigrant children'), with a note that the official definition included children born in Britain.",self_id:"",note:"",debated:false,re:"\\bimmigrant (children|pupils)\\b",named:false,covers:[],src:[SRCQ("Journal of Social Policy (Cambridge University Press), Immigrant Children: A Review of Problems and Policy in Education (abstract)","https://www.cambridge.org/core/journals/journal-of-social-policy/article/abs/immigrant-children-a-review-of-problems-and-policy-in-education/B15318CB22A0FFCAD22F70134CFD2C5C","Supports the language page (language of the time)","The Department of Education defines an immigrant child as one either born abroad | or born in U.K. to a parent or parents whose origin was abroad, and who came to Britain less than ten years ago."),SRCQ("DES Circular 7/65 (1965), The Education of Immigrants (education-uk.org transcription)","https://education-uk.org/documents/des/circular7-65.html","Supports the language page (language of the time)","disperse the immigrant children round a greater number of schools | if the proportion goes over about one third either in the school as a whole or in any one class, serious strains arise"),SRCQ("Discover Society, Babylon By Bus? (Olivier Esteves, 2019)","https://archive.discoversociety.org/2019/04/03/babylon-by-bus-the-introduction-of-and-the-resistance-to-bussing-in-southall-and-elsewhere/","Supports the language page (language of the time)","\"immigrant children\" had not been defined | which in practice was colour-based"),SRCQ("Margaret Thatcher Foundation, Select Committee on Race Relations and Immigration (Education), 20 June 1973, DES memorandum","https://www.margaretthatcher.org/document/102286","Supports the language page (language of the time)","To alter the period of time after which immigrant pupils are assumed to be no longer in need of special help")]},
 {id:"lt-esn",term:"ESN / educationally subnormal",period:"A statutory category of 'handicap' in English special education from the 1940s until the Education Act 1981 replaced categories with 'special educational needs' (following the Warnock Report, 1978).",meaning_then:"A label for children judged (often by IQ test) to have low intelligence, who could be sent to separate 'ESN schools'. Caribbean-heritage children were placed in ESN schools in disproportionate numbers, exposed by Bernard Coard's 1971 pamphlet 'How the West Indian Child is Made Educationally Sub-normal in the British School System'.",why_changed:"The category system was abolished in 1981 as too narrow and stigmatising; campaigners showed racial bias in testing and referrals.",hub_uses_now:"'Special educational needs' for the modern system; for history, 'so-called ESN schools' with the label explained.",when_kept:"Kept in Coard's title, in quotations from school and local authority records, and as the name of the schools of the time, in quotation marks, with a note that it was an official category later abolished and that Black children were wrongly placed in these schools.",self_id:"",note:"",debated:false,re:"\\beducationally subnormal\\b|\\bESN\\b",named:true,covers:[],src:[SRCQ("Black Cultural Archives (Google Arts & Culture), A history of education campaigning","https://artsandculture.google.com/story/a-history-of-education-campaigning-black-cultural-archives/cQXhZVzwN7aDKg?hl=en","Supports the language page (language of the time)","Coard looked at the high numbers of Black children who were being placed in schools for 'the educationally sub-normal' | ESN schools were originally created to deal with children who had low intelligence"),SRCQ("IBHM UK, Bernard Coard: educator, author and catalyst for change in Black education","https://www.ibhm-uk.org/post/bernard-coard-educator-author-and-catalyst-for-change-in-black-education","Supports the language page (language of the time)","highlighted the disproportionate placement of Black Caribbean children into \"Educationally Sub-Normal\" (ESN) schools."),SRCQ("Special Needs in Education, White Paper Cmnd 7996 (1980) (education-uk.org transcription)","https://education-uk.org/documents/official-papers/1980-wp-special-needs.html","Supports the language page (language of the time)","ascertained as belonging to a category of handicap. | the adoption of the concept of special educational needs")]},
 {id:"lt-bame-bme",term:"BAME / BME",period:"BME (Black and minority ethnic) and BAME (Black, Asian and minority ethnic) were widely used in UK public bodies from the 1990s/2000s until government committed to stop using 'BAME' in March 2022 (response to the Commission on Race and Ethnic Disparities); universities and others followed.",meaning_then:"Umbrella acronyms for all ethnic minority groups (sometimes including white minorities), used in government statistics, NHS, council and university reports and funding schemes.",why_changed:"They group very different people together, can hide disparities between groups, centre whiteness as the norm, and many people do not like being described by an acronym.",hub_uses_now:"Specific ethnic groups where possible; otherwise 'ethnic minorities' or 'people from ethnic minority backgrounds' (UK government usage).",when_kept:"Kept in report titles, network and organisation names (for example staff networks or funds named before 2022) and in quotations, with a note that the UK government stopped using BAME in 2022 and why.",self_id:"Some organisations and networks still carry the acronym in their names.",note:"Replacement umbrella terms (people of colour, Global Majority, ethnically diverse) are themselves debated; see lt-people-of-colour.",debated:false,re:"\\b(BAME|BME)\\b",named:false,covers:["BAME", "BME"],src:[SRCQ("GOV.UK Equality Hub blog, Why we no longer use the term 'BAME' in government (7 April 2022)","https://equalities.blog.gov.uk/2022/04/07/why-we-no-longer-use-the-term-bame-in-government/","Supports the language page (language of the time)","It also includes a commitment to no longer use the term 'BAME' in government. | This can disguise huge differences in outcomes between ethnic groups."),SRCQ("GOV.UK Ethnicity facts and figures, Writing about ethnicity","https://www.ethnicity-facts-figures.service.gov.uk/style-guide/writing-about-ethnicity/","Supports the language page (language of the time)","We do not use the terms BAME (Black, Asian and minority ethnic) and BME (Black and minority ethnic) | The terms can also mask disparities between different ethnic groups"),SRCQ("University of Bath, Guidance on the categorisation of ethnicity","https://www.bath.ac.uk/guides/guidance-on-the-categorisation-of-ethnicity/","Supports the language page (language of the time)","The term BAME (Black, Asian and Minority Ethnic) has long been used in institutional publications"),SRCQ("International Slavery Museum (National Museums Liverpool), Guidance on subject sensitivity and language (24 October 2022)","https://images.liverpoolmuseums.org.uk/2022-11/ISM-guidance-subject-sensitivity-language-24-Oct-22.pdf","Supports the language page (language of the time)","The term BAME groups non-white people together making white people seem the norm."),SRCQ("Bar Council, Equality and Diversity Guides: Race Terminology (November 2020)","https://www.barcouncilethics.co.uk/wp-content/uploads/2020/12/Bar-Council_ED-Guides_Race-Terminology_November-2020-1.pdf","Supports the language page (language of the time)","the term BAME is disliked and many feel othered by the use of the term.")]},
 {id:"lt-tribe",term:"tribe / tribal",period:"Applied by European colonial administrations and anthropologists to African peoples from the 19th century; still common in Western media; also a legal and self-chosen term for Native American nations and used by many Africans in English.",meaning_then:"In colonial Africa 'tribe' became a cornerstone of indirect rule: peoples were sorted into fixed 'tribes' with appointed chiefs, and the word implied primitiveness and timeless, rigid divisions.",why_changed:"Scholars argue the term has no consistent meaning, was partly invented or hardened by colonial rule, and carries racial stereotypes of primitiveness that are not applied to European peoples; it also hides modern political causes of conflict.",hub_uses_now:"'People', 'ethnic group', 'nation', 'community' or the group's own name (e.g. 'the Yoruba people', 'the Zulu nation'). Keeps 'tribe' or 'tribal nation' where communities use it for themselves.",when_kept:"Kept in colonial document titles and quotations (with a note on colonial usage), in self-designations (for example US federally recognised tribes and tribal nations) and when Africans quoted use it themselves.",self_id:"Native American tribal nations use 'tribe' and 'tribal nation' as legal and political self-names; many Africans use 'tribe' in English without the Western connotations of primitiveness.",note:"One view: avoid 'tribe' for African peoples because of its colonial and racial baggage. Other view: many Africans and Indigenous nations use it themselves, so it should be respected where it is the community's own word.",debated:true,re:"\\btrib(e|es|al)\\b",named:false,covers:["tribe"],src:[SRCQ("Africa Policy Information Center, Talking about 'Tribe': Moving from Stereotypes to Analysis (1997), via University of Pennsylvania African Studies Center","https://www.africa.upenn.edu/Urgent_Action/apic_122197.html","Supports the language page (language of the time)","The term \"tribe\" has no consistent meaning. | Tribe became a cornerstone idea for European colonial rule in Africa. | Many Africans themselves use the word \"tribe\" when speaking or writing in English"),SRCQ("Monash University, Writing Africa into MOS: the dangerous perpetuation of 'tribe(s)' and other misrepresentations (abstract)","https://research.monash.edu/en/publications/writing-africa-into-mos-the-dangerous-perpetuation-of-tribes-and-/","Supports the language page (language of the time)","the invention of \"tribes\" by European colonizers to subjugate and control African people during colonialism"),SRCQ("National Congress of American Indians, Tribal governance","https://archive.ncai.org/policy-issues/tribal-governance","Supports the language page (language of the time)","The US Constitution recognizes that tribal nations are sovereign governments, just like Canada or California."),SRCQ("Merriam-Webster, tribe","https://www.merriam-webster.com/dictionary/tribe","Supports the language page (language of the time)","a community composed chiefly of numerous families, clans, or generations who have a shared ancestry, culture, and language")]},
 {id:"lt-slave-enslaved",term:"slave / slave-owner / slave trade (and 'enslaved people', 'enslaver')",period:"'Slave', 'slave-owner', 'slaveholder' and 'slave trade' were the standard terms in law, abolition campaigns and records (e.g. Slave Trade Act 1807, Slavery Abolition Act 1833, Slave Compensation records). 'Enslaved people' and 'enslaver' have spread since the 2000s-2010s in museums and scholarship.",meaning_then:"'Slave' described a person held as property; 'slave-owner' the person holding them; 'slave trade' the buying and selling of people, above all the transatlantic trade in Africans.",why_changed:"Many museums and scholars prefer 'enslaved African/person' because it stresses that slavery was done to people, not who they were, and 'slave' can be dehumanising. Some historians argue 'enslaved person' is not a universal replacement and that 'enslaver' blurs ownership, preferring 'slaveholder' or 'slave owner'.",hub_uses_now:"'Enslaved people' / 'enslaved Africans' for people; 'enslavers' or 'slave owners' for those who held them, as fits the context; 'transatlantic slave trade' and 'transatlantic slavery' as the established names.",when_kept:"Kept unchanged in titles of laws (Slave Trade Act 1807, Slavery Abolition Act 1833), record series and databases (e.g. UCL Legacies of British Slave-ownership, 'slave registers'), book and exhibition titles and quotations from documents, with a short note on the hub's own wording.",self_id:"",note:"For 'enslaved/enslaver': emphasises humanity and that enslavement was imposed (International Slavery Museum and many community-led guides). Against universal use: James Robert Burns (Transactions of the Royal Historical Society, 2024) argues 'slave' need not dehumanise and 'enslaver' obscures ownership. The hub prefers 'enslaved people' but keeps historical titles.",debated:true,re:"\\bslaves?\\b|\\bslave[- ]?owners?\\b|\\bslave[- ]traders?\\b",named:false,covers:["slaves", "slave-owner", "slave trader"],src:[SRCQ("International Slavery Museum (National Museums Liverpool), Guidance on subject sensitivity and language (24 October 2022)","https://images.liverpoolmuseums.org.uk/2022-11/ISM-guidance-subject-sensitivity-language-24-Oct-22.pdf","Supports the language page (language of the time)","Instruct pupils to use the term 'enslaved Africans' rather than 'slaves' as it is too generalised and dehumanising a term."),SRCQ("James Robert Burns, 'Slaves' and 'Slave Owners' or 'Enslaved People' and 'Enslavers'?, Transactions of the Royal Historical Society (2024)","https://www.cambridge.org/core/services/aop-cambridge-core/content/view/8442245D3523F8DB72C653A7EE9FB5C7/S0080440123000282a.pdf/slaves-and-slave-owners-or-enslaved-people-and-enslavers.pdf","Supports the language page (language of the time)","Despite the commendable intentions behind it, 'enslaved person' is not convincing as a universal substitute for 'slave'. | 'Slaveholder' or 'slave owner' are better than both terms."),SRCQ("UCL News, New Centre for the Study of the Legacies of British Slave-ownership launched at UCL (2016)","https://www.ucl.ac.uk/news/2016/sep/new-centre-study-legacies-british-slave-ownership-launched-ucl","Supports the language page (language of the time)","Centre for the Study of the Legacies of British Slave-ownership | contains some 20,000 newly researched slave-owners and over 8000 estates")]},
 {id:"lt-colonial-classifications",term:"mulatto, quadroon, octoroon and similar colonial-era classifications",period:"From the late 16th century (mulatto, 1591) through the 18th-19th centuries in the Americas and Caribbean; used in plantation, colonial and US census records (Mulatto from 1850; quadroon and octoroon in 1890).",meaning_then:"Labels that sorted people by fractions of supposed 'Black blood' to fix their legal and social status in slave societies; the root of 'mulatto' compares a person to a mule.",why_changed:"They are based on race-science ideas of blood quantum and hierarchy and were used to police status in slavery and segregation; dictionaries label them offensive.",hub_uses_now:"'Of mixed African and European descent', 'mixed heritage', or the person's own description.",when_kept:"The hub names the term itself once, in quotation marks, when explaining a census, register or legal category (e.g. '1890 US Census categories'), and explains it was an imposed racial classification. It does not reproduce longer lists of such labels or the racist reasoning behind them; that is paraphrased.",self_id:"",note:"",debated:false,re:"\\b(mulatto|quadroon|octoroon)s?\\b",named:false,covers:[],src:[SRCQ("Merriam-Webster, mulatto","https://www.merriam-webster.com/dictionary/mulatto","Supports the language page (language of the time)","usually offensive | Spanish mulato, from mulo mule | First known use: 1591"),SRCQ("Merriam-Webster, quadroon","https://www.merriam-webster.com/dictionary/quadroon","Supports the language page (language of the time)","dated, offensive | First known use: 1780"),SRCQ("Pew Research Center, What Census calls us / The changing categories the U.S. census has used to measure race (2020)","https://pewresearch.org/fact-tank/2020/02/25/the-changing-categories-the-u-s-has-used-to-measure-race/","Supports the language page (language of the time)","mulattos (generally defined as someone who is black and at least one other race) | the racial categories of \"quadroon\" (defined as one-fourth \"black blood\")"),SRCQ("US Census Bureau, Measuring Race and Ethnicity Across the Decades: 1790-2010","https://www.census.gov/data-tools/demo/race/MREAD_1790_2010.html","Supports the language page (language of the time)","measuring a 'Black blood' quantum, termed 'Mulatto,' for free inhabitants and slave inhabitants")]},
 {id:"lt-dark-continent",term:"Dark Continent",period:"From the 19th century (Merriam-Webster first known use 1829), popularised by Victorian explorers and writers.",meaning_then:"A European name for Africa presenting it as unknown, unexplored and 'dark'.",why_changed:"Historians describe it as a Victorian myth that justified imperial expansion. Already covered on the hub: cross-reference the existing Dark Continent entry.",hub_uses_now:"Africa / the African continent; see the hub's existing entry.",when_kept:"Kept only in quoted titles and period sources, with a link to the hub's existing explanation.",self_id:"",note:"Cross-reference only: the hub already covers this term.",debated:false,re:"\\bDark Continent\\b",named:false,covers:["Dark Continent"],src:[SRCQ("Merriam-Webster, Dark Continent","https://www.merriam-webster.com/dictionary/Dark%20Continent","Supports the language page (language of the time)","the continent of Africa | something unknown or unexplored"),SRCQ("Critical Inquiry (University of Chicago), Patrick Brantlinger","https://criticalinquiry.uchicago.edu/authors/author/patrick_brantlinger","Supports the language page (language of the time)","Victorians and Africans: The Genealogy of the Myth of the Dark Continent")]},
 {id:"lt-race-census",term:"'race' in census and official categories",period:"US censuses recorded race from 1790 (by enumerator observation until 1960). Britain used birthplace (e.g. 'New Commonwealth', 1966) and 'White or coloured' survey codes before the 1991 Census first asked an ethnic group question. UK law (Equality Act 2010) still uses 'race'.",meaning_then:"'Race' categories were assigned by officials and reflected racial theories of the day (including 'blood quantum' categories). Later, self-identification replaced official observation.",why_changed:"UK statistics now ask about ethnicity, a matter of self-identification, rather than 'race'; 'race' remains the legal term for the protected characteristic and is used when discussing racism and racial inequality.",hub_uses_now:"'Ethnicity' or 'ethnic group' for data; 'race' and 'racism' when discussing discrimination and law; historical category names quoted and explained.",when_kept:"Kept exactly as printed when quoting census forms, legislation (Race Relations Acts; Equality Act 'race'), and historical categories, with an explanation of who assigned them and how.",self_id:"",note:"",debated:false,re:null,named:false,covers:[],src:[SRCQ("GOV.UK Ethnicity facts and figures, Writing about ethnicity","https://www.ethnicity-facts-figures.service.gov.uk/style-guide/writing-about-ethnicity/","Supports the language page (language of the time)","We refer to ethnicity and not race. | surveys usually ask people for their ethnicity and not their race"),SRCQ("GOV.UK History of Government blog, 50 years of collecting ethnicity data (2019)","https://history.blog.gov.uk/2019/03/07/50-years-of-collecting-ethnicity-data/","Supports the language page (language of the time)","The 1991 Census was the first to include an ethnicity question. | Race is described in terms of a person's skin colour, nationality, and ethnic or national origins."),SRCQ("Bar Council, Equality and Diversity Guides: Race Terminology (November 2020)","https://www.barcouncilethics.co.uk/wp-content/uploads/2020/12/Bar-Council_ED-Guides_Race-Terminology_November-2020-1.pdf","Supports the language page (language of the time)","We recommend using the term 'race' when referring to specific work on racial inequalities or discrimination | We recommend using the term 'ethnicity' in the context of collection and breakdown of data"),SRCQ("US Census Bureau, Measuring Race and Ethnicity Across the Decades: 1790-2010","https://www.census.gov/data-tools/demo/race/MREAD_1790_2010.html","Supports the language page (language of the time)","Data on race were recorded via enumerator observation. | self-response replaced enumerator reporting for most Americans.")]},
 {id:"lt-new-commonwealth",term:"New Commonwealth (NCWP)",period:"UK official statistics from the 1960s to the 1980s (e.g. 1966 sample Census; 'New Commonwealth and Pakistan', NCWP).",meaning_then:"A birthplace grouping for countries that joined the Commonwealth after 1945, such as India, Pakistan, Bangladesh and the West Indies, used as a stand-in for ethnic minority populations.",why_changed:"Birthplace is a poor indicator of ethnicity (it excludes British-born children and includes white people born abroad); replaced by the ethnic group question from 1991.",hub_uses_now:"Specific countries of birth or ethnic groups.",when_kept:"Kept in quotations from statistics and reports, explained as a birthplace grouping that was used as a proxy for 'non-white' in official data.",self_id:"",note:"",debated:false,re:"\\bNew Commonwealth\\b",named:true,covers:[],src:[SRCQ("GOV.UK History of Government blog, 50 years of collecting ethnicity data (2019)","https://history.blog.gov.uk/2019/03/07/50-years-of-collecting-ethnicity-data/","Supports the language page (language of the time)","India, Pakistan, Bangladesh and the West Indies | It is hard to see these groups as good indicators of ethnicity."),SRCQ("UCL Faculty of Population Health Sciences, ethnicity guide (2026)","https://www.ucl.ac.uk/population-health-sciences/sites/population_health_sciences/files/2026-07/FPHS_pdf_ethnicity-guide_20260713_na_0.pdf","Supports the language page (language of the time)","is used for those born outside the NCWP, with one parent born in the NCWP.")]},
 {id:"lt-afro-caribbean",term:"Afro-Caribbean (and African Caribbean)",period:"Recorded from 1959 (Merriam-Webster); taken up in British research and official usage in the 1980s as a replacement for 'West Indian'; replaced in the Census by 'Black-Caribbean' (1991) and 'Caribbean' under 'Black, Black British, Caribbean or African' (2021).",meaning_then:"A person of African descent born or living in the Caribbean, or of that heritage in Britain; used widely in 1980s-90s British reports, community centres and organisation names.",why_changed:"Official statistics settled on 'Black Caribbean' / 'Caribbean'; many writers now prefer the full 'African Caribbean' to the prefix 'Afro-'. (No dictionary or official source found that labels 'Afro-Caribbean' offensive; this is a shift in preference, not a ban.)",hub_uses_now:"'Black Caribbean' or 'Caribbean' (official categories) and 'African Caribbean' in prose; the hub's choice of 'African Caribbean' is an editorial preference.",when_kept:"Kept unchanged in organisation names, report titles and quotations (e.g. Afro-Caribbean community associations and centres), with a note that it was the usual term from the 1980s.",self_id:"Still used by many people and organisations of Caribbean heritage in Britain.",note:"",debated:false,re:"\\bAfro-Caribbean\\b",named:true,covers:[],src:[SRCQ("Merriam-Webster, Afro-Caribbean","https://www.merriam-webster.com/dictionary/Afro-Caribbean","Supports the language page (language of the time)","a person of African descent born or living in a Caribbean nation | First known use: 1959"),SRCQ("GOV.UK History of Government blog, 50 years of collecting ethnicity data (2019)","https://history.blog.gov.uk/2019/03/07/50-years-of-collecting-ethnicity-data/","Supports the language page (language of the time)","'Afro-Caribbean' | 'West Indian' | White; Black-Caribbean; Black-African; Black-Other (write in);"),SRCQ("GOV.UK Ethnicity facts and figures, List of ethnic groups","https://www.ethnicity-facts-figures.service.gov.uk/style-guide/ethnic-groups/","Supports the language page (language of the time)","Black, Black British, Caribbean or African | Caribbean | White and Black Caribbean")]},
 {id:"lt-mixed-race",term:"mixed race / Mixed ethnic background",period:"'Mixed race' widely used in Britain from the later 20th century; the 'Mixed' group was added to the Census in 2001 (now 'Mixed or multiple ethnic groups').",meaning_then:"Replaced older terms such as 'half-caste' as a neutral description of people with parents or ancestors of different ethnic groups.",why_changed:"Some reject 'mixed race' because it implies that distinct 'races' exist, and prefer 'mixed heritage', 'dual heritage' or 'multiple heritage'; UK government statistics avoid 'Mixed race people' and use 'Mixed ethnic background'. Others identify strongly as mixed race.",hub_uses_now:"'Mixed ethnic background' or 'Mixed or multiple ethnic groups' for statistics; 'mixed heritage' or 'mixed race' in prose, following the person's own choice.",when_kept:"Kept where people describe themselves as mixed race, and in titles, organisations and quotations.",self_id:"Many people describe themselves as mixed race; others prefer mixed heritage or dual heritage.",note:"View 1: 'mixed race' is widely used and accepted, and is many people's own identity (EqualiTeach; Equal Treatment Bench Book: acceptable to some). View 2: it implies biological races and is avoided in official writing; prefer 'Mixed ethnic background' or 'mixed heritage' (GOV.UK; some people reject it). The hub follows self-description.",debated:true,re:"\\bmixed[- ]race\\b",named:false,covers:[],src:[SRCQ("GOV.UK Ethnicity facts and figures, Writing about ethnicity","https://www.ethnicity-facts-figures.service.gov.uk/style-guide/writing-about-ethnicity/","Supports the language page (language of the time)","However, we don't say 'Mixed people' or 'Mixed race people'. | We usually say 'people with a Mixed ethnic background' or 'people from the Mixed ethnic group'."),SRCQ("EqualiTeach, Equality terminology (hosted by the Royal Institution)","https://www.rigb.org/sites/default/files/attachments/equality_terminology__equaliteach_0.pdf","Supports the language page (language of the time)","An acceptable term | reject the term 'mixed race' and instead use other terms such as 'mixed heritage' or 'dual heritage'"),SRCQ("5 Essex Court (barristers' chambers), summary of the Judicial College Equal Treatment Bench Book (2024 edition) terminology guidance","https://www.5essex.co.uk/the-latest-edition-of-the-equal-treatment-bench-book-gives-guidance-on-the-appropriate-use-of-terminology/","Supports the language page (language of the time)","The term 'mixed race' is still widely used and is considered acceptable by some, though not by others."),SRCQ("UCL Faculty of Population Health Sciences, ethnicity guide (2026)","https://www.ucl.ac.uk/population-health-sciences/sites/population_health_sciences/files/2026-07/FPHS_pdf_ethnicity-guide_20260713_na_0.pdf","Supports the language page (language of the time)","A new Mixed group is included in 2001")]},
 {id:"lt-people-of-colour",term:"people of colour",period:"Originated in the United States; increasingly used in Britain since the 2010s, including as an alternative to BAME.",meaning_then:"A collective term for people who are not white, often used in solidarity and self-description.",why_changed:"Not a historical term being retired but a live, debated one: some welcome it as self-chosen and political; others say it still groups very different people together, is US-centred, and echoes 'coloured'. Already covered on the hub: cross-reference.",hub_uses_now:"Specific groups where possible; 'people of colour' when quoting or when people use it of themselves; see the hub's existing entry.",when_kept:"Kept in quotations, organisation names and where people self-identify with it.",self_id:"Used by many people and organisations as a self-chosen collective identity.",note:"For: widely used and self-chosen (EqualiTeach calls it acceptable; Bar Council notes wide use). Against: still lumps groups together; more US than UK usage (Equal Treatment Bench Book); single replacement terms for BAME impose categories (Bar Council). Cross-reference the hub's existing entry.",debated:true,re:"\\bpeople of colou?r\\b",named:false,covers:[],src:[SRCQ("EqualiTeach, Equality terminology (hosted by the Royal Institution)","https://www.rigb.org/sites/default/files/attachments/equality_terminology__equaliteach_0.pdf","Supports the language page (language of the time)","A term, which originated in the United States of America."),SRCQ("Bar Council, Equality and Diversity Guides: Race Terminology (November 2020)","https://www.barcouncilethics.co.uk/wp-content/uploads/2020/12/Bar-Council_ED-Guides_Race-Terminology_November-2020-1.pdf","Supports the language page (language of the time)","'People of colour' and 'Black, Asian and ethnically diverse' | These are widely used and are politically correct."),SRCQ("5 Essex Court (barristers' chambers), summary of the Judicial College Equal Treatment Bench Book (2024 edition) terminology guidance","https://www.5essex.co.uk/the-latest-edition-of-the-equal-treatment-bench-book-gives-guidance-on-the-appropriate-use-of-terminology/","Supports the language page (language of the time)","The term 'people of colour' tends to be used more in the USA than in the UK.")]},
 {id:"lt-blak",term:"Blak (Australia)",period:"Coined by the Aboriginal artist Destiny Deacon in the early 1990s (her work 'Blak lik mi', 1991); adopted widely since, including in the 2024 NAIDOC Week theme.",meaning_then:"A reclaiming of 'Black', a label colonists applied to First Nations people, by removing the 'c'.",why_changed:"It is a modern self-identification rather than a historical term; included so the hub can explain it respectfully when quoting Aboriginal and Torres Strait Islander sources.",hub_uses_now:"Uses 'Blak' only as First Nations people use it of themselves, e.g. when quoting or naming events and works.",when_kept:"Always kept as written in names, titles and quotations from First Nations people, with a note on its origin.",self_id:"Embraced by many Aboriginal and Torres Strait Islander people as a signifier of identity.",note:"A self-identification: the hub explains it and does not apply it to people outside Australian First Nations contexts.",debated:false,re:"\\bBlak\\b",named:true,covers:[],src:[SRCQ("National Gallery of Australia, Destiny Deacon obituary","https://nga.gov.au/about-us/obituaries/destiny-deacon","Supports the language page (language of the time)","removing the 'c' from a label applied to First Nations people by colonists | flipping them to reclaim power that the term or image sought to withhold"),SRCQ("Clothing the Gaps (Aboriginal-led social enterprise), A tribute to Destiny Deacon","https://www.clothingthegaps.com.au/blogs/blogs/blak","Supports the language page (language of the time)","symbolises a reclaiming of Indigenous identity and resistance against derogatory language | Today, the word 'Blak' is embraced by many First Nations people across the continent as a signifier for identity.")]},
 {id:"lt-non-white",term:"non-white",period:"20th century to the 2010s in UK and US statistics and reports",meaning_then:"A grouping of everyone not classed as White, used in statistics, law and reports, for example in the history of 1962 to 1971 immigration law.",why_changed:"It defines people only by what they are not, in relation to the White majority, and hides differences between groups. UK government guidance says this framing was not well received in user research.",hub_uses_now:"The specific ethnic groups, or 'ethnic minorities' for all groups except White British.",when_kept:"In quotations from historical documents and statistics, with this explanation.",self_id:"",note:"",debated:false,re:"\\bnon-[Ww]hite\\b",named:false,covers:["non-white"],src:[SRCQ("Writing about ethnicity (Ethnicity facts and figures, GOV.UK)","https://www.ethnicity-facts-figures.service.gov.uk/style-guide/writing-about-ethnicity/","Supports the language page (language of the time)","We do not use ‘non-White’ because defining groups in relation to the White majority was not well received in user research."),SRCQ("Race and national origin (NIH style guide)","https://www.nih.gov/nih-style-guide/race-national-origin","Supports the language page (language of the time)","Avoid collective reference to racial and ethnic minority groups as non-White unless it was a formal category in a database")]},
];
